import{_ as n,o as i,c as o,a5 as e}from"./chunks/framework.CsGesDJn.js";const d=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"feature/content-task-workflow/3-6-17-apply-hashtag/report3_spec.md","filePath":"feature/content-task-workflow/3-6-17-apply-hashtag/report3_spec.md"}'),c={name:"feature/content-task-workflow/3-6-17-apply-hashtag/report3_spec.md"};function h(a,t,s,r,l,g){return i(),o("div",null,[...t[0]||(t[0]=[e("<p><strong>3.6.17 Apply Hastag</strong></p><p><strong>Function Trigger</strong></p><p>Begins when CREATOR thực hiện thao tác trên giao diện <code>Apply Hastag Page</code> liên quan đến tính năng <code>Apply Hastag</code>.</p><p><strong>Function Description</strong></p><ul><li><strong>Actors / Roles</strong>: CREATOR.</li><li><strong>Purpose</strong>: Thêm hastag có thể một hoặc nhiều cho bài đăng hoặc bài sự kiện chiến dịch.</li><li><strong>Interface</strong>: Giao diện <code>Apply Hastag Page</code> hiển thị trực quan các thành phần thao tác, dữ liệu và phản hồi trạng thái.</li><li><strong>Data Processing</strong>: Tiếp nhận yêu cầu tại <code>HashtagController</code>, xác thực quyền của caller, thực thi kiểm tra và xử lý nghiệp vụ thông qua <code>HashtagService</code>, truy xuất và cập nhật cơ sở dữ liệu thông qua Repository tương ứng.</li></ul><p><strong>Screen Layout</strong></p><p>Figure — Screen Layout (<code>Apply Hastag Page</code>):</p><ul><li>Header: Tiêu đề trang, breadcrumb điều hướng và thông tin định danh ngữ cảnh làm việc.</li><li>Main Workspace: Khu vực hiển thị bảng dữ liệu, biểu mẫu nhập liệu hoặc danh sách đối tượng nghiệp vụ.</li><li>Action Panel: Các nút điều khiển thực hiện hành động chính, nút hủy và các bộ lọc tìm kiếm.</li><li>Feedback Area: Khu vực hiển thị trạng thái xử lý (loading spinner, modal xác nhận, toast thông báo kết quả).</li></ul><p><strong>Function Details</strong></p><ul><li><p><strong>Data Specifications</strong></p><ul><li><strong>Input required</strong>: Các trường bắt buộc theo đặc tả của <code>PATCH /api/v1/workspaces/{workspaceId}/tasks/{taskId}/hashtags</code>.</li><li><strong>Input optional</strong>: Các tham số lọc, phân trang hoặc ghi chú bổ sung.</li><li><strong>System data</strong>: Bản ghi dữ liệu liên quan tại các bảng cơ sở dữ liệu (<code>Web dashboard, WorkspaceRepository, WorkspaceMemberRepository, AgencyRepository, HashtagRepository, TaskHashtagRepository</code>).</li><li><strong>Output</strong>: <code>ApiResponse</code> kèm mã trạng thái HTTP tiêu chuẩn.</li></ul></li><li><p><strong>Business Rules</strong></p><ul><li><strong>BR-3617</strong>: Chỉ các Actor có thẩm quyền hợp lệ (<code>CREATOR</code>) mới được phép kích hoạt tính năng.</li><li>Đảm bảo tính toàn vẹn dữ liệu và kiểm tra xung đột trạng thái trước khi thực hiện thay đổi dữ liệu.</li><li>Mọi thao tác đều được ghi nhận nhật ký hệ thống phục vụ công tác kiểm toán và giám sát.</li></ul></li><li><p><strong>Validation</strong></p><ul><li>Thiếu hoặc sai định dạng tham số bắt buộc → Trả về HTTP 400 <code>BAD_REQUEST</code>.</li><li>Token không hợp lệ hoặc hết hạn → Trả về HTTP 401 <code>UNAUTHORIZED</code>.</li><li>Không đủ thẩm quyền vai trò → Trả về HTTP 403 <code>FORBIDDEN</code>.</li><li>Bản ghi đối tượng không tồn tại → Trả về HTTP 404 <code>NOT_FOUND</code>.</li></ul></li></ul><p><strong>Functionalities</strong></p><ul><li><p><strong>Normal Flow</strong></p><ol><li>Gửi yêu cầu <code>Check active tags, version and required scope</code> từ <code>hashtagservice</code> tới <code>hashtagservice</code>.</li><li>Gửi yêu cầu <code>Check CREATOR and destination rights</code> từ <code>hashtagservice</code> tới <code>hashtagservice</code>.</li><li>Gửi yêu cầu <code>Merge tags; keep snapshots</code> từ <code>hashtagservice</code> tới <code>hashtagservice</code>.</li><li>Gửi yêu cầu <code>Resolve coordinated writeOutcome</code> từ <code>hashtagservice</code> tới <code>hashtagservice</code>.</li><li>Gửi yêu cầu <code>Select hashtags and Apply to Post</code> từ <code>creator</code> tới <code>webdashboard</code>.</li></ol></li><li><p><strong>Abnormal Cases</strong></p><ul><li>2.a1: Token xác thực không hợp lệ hoặc hết hạn → Hệ thống hiển thị thông báo lỗi và yêu cầu đăng nhập lại.</li><li>3.a1: Dữ liệu đầu vào không thỏa mãn ràng buộc nghiệp vụ → Hệ thống báo lỗi chi tiết tại từng trường nhập liệu.</li><li>4.a1: Đối tượng yêu cầu không tồn tại trong hệ thống → Hiển thị thông báo không tìm thấy bản ghi tương ứng.</li></ul></li></ul><p><strong>Post-Conditions</strong></p><ul><li>Trạng thái hệ thống được cập nhật chính xác theo kết quả xử lý của tính năng <code>Apply Hastag</code>.</li><li>Người dùng nhận được phản hồi trực quan trên giao diện và luồng nghiệp vụ được tiếp diễn theo kế hoạch.</li></ul>",14)])])}const u=n(c,[["render",h]]);export{d as __pageData,u as default};
